import { afterEach, describe, expect, it } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

// The native project is generated by the APK builder, so exercise real files
// with the same launch-theme/resource structure here, not browser screenshots.
const roots: string[] = [];
afterEach(() => { for (const root of roots.splice(0)) fs.rmSync(root, { recursive: true, force: true }); });

describe('native startup patch', () => {
  it('replaces the Capacitor launch image on old and Android 12 themes without changing launcher assets', async () => {
    const { fixAndroidStartup } = await import('../../scripts/fix-android-startup.mjs');
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'ikayi-startup-'));
    roots.push(root);
    const main = path.join(root, 'android/app/src/main');
    fs.mkdirSync(path.join(main, 'res/values'), { recursive: true });
    fs.mkdirSync(path.join(main, 'res/mipmap-hdpi'), { recursive: true });
    const iconPath = path.join(main, 'res/mipmap-hdpi/ic_launcher.png');
    fs.writeFileSync(iconPath, 'approved launcher image');
    fs.writeFileSync(path.join(main, 'AndroidManifest.xml'), '<manifest><application><activity android:theme="@style/AppTheme.NoActionBarLaunch"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity></application></manifest>');
    fs.writeFileSync(path.join(main, 'res/values/styles.xml'), '<resources><style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen"><item name="android:windowBackground">@drawable/splash</item><item name="postSplashScreenTheme">@style/AppTheme.NoActionBar</item></style></resources>');
    fixAndroidStartup(root);
    const legacy = fs.readFileSync(path.join(main, 'res/values/styles.xml'), 'utf8');
    const modern = fs.readFileSync(path.join(main, 'res/values-v31/styles.xml'), 'utf8');
    expect(legacy).not.toContain('@drawable/splash');
    expect(modern).toContain('name="android:windowSplashScreenAnimatedIcon">@drawable/ikayi_startup_blank');
    expect(modern).toContain('name="postSplashScreenTheme">@style/AppTheme.NoActionBar');
    expect(fs.readFileSync(iconPath, 'utf8')).toBe('approved launcher image');
    fixAndroidStartup(root);
    expect(fs.readFileSync(path.join(main, 'res/values-v31/styles.xml'), 'utf8')).toBe(modern);
  });

  it('stops if the generated Android project is missing', async () => {
    const { fixAndroidStartup } = await import('../../scripts/fix-android-startup.mjs');
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'ikayi-missing-'));
    roots.push(root);
    expect(() => fixAndroidStartup(root)).toThrow('Android project missing');
  });
});